 const string D="Assets/M/CodexTemp/ElevatorInteraction_20261030~/";static List<object> checks=new List<object>();static void Check(bool b,string name){checks.Add(new{name,passed=b});if(!b)throw new Exception(name);}
 public static async Task<string> Main(){AssetDatabase.ImportAsset("Assets/M/Arts/Shaders/ElevatorSkyHighlightMask.shader",ImportAssetOptions.ForceUpdate);var l=UnityEngine.Object.FindFirstObjectByType<ElevatorLesson>();var c=UnityEngine.Object.FindFirstObjectByType<ElevatorDesktopControls>();var p=l.pauseMenu;string error=null;try{
 l.Restart();l.presentation.space.overlay.Advance(2);l.Continue();await Task.Delay(650);Check(l.Flow.Step==ElevatorStep.Entering,"Boarding animation starts");p.Pause();var pos=c.xrOrigin.position;var door=l.presentation.space.sportsCentre.DoorOpen;var elapsed=l.Flow.Elapsed;await Task.Delay(650);Check(c.xrOrigin.position==pos&&Mathf.Abs(door-l.presentation.space.sportsCentre.DoorOpen)<.001f&&Mathf.Abs(elapsed-l.Flow.Elapsed)<.001f,"Pause freezes scripted boarding and doors");p.Resume();await Task.Delay(300);Check(l.Flow.Elapsed>elapsed,"Scripted boarding resumes");
