 l.DeveloperJump(6);l.Advance(4);l.Continue();l.Advance(5);l.Continue();l.Advance(4);l.Continue();l.Advance(7);l.presentation.space.overlay.Advance(2);await Task.Delay(700);Check(Mathf.Abs(l.playerCamera.transform.position.y-c.eyeHeight)<.08f,"Player remains grounded on exterior courtyard after completion");var book=l.view.spatial.notebook;var step=l.Flow.Step;Check(step==ElevatorStep.Complete&&book.gameObject.activeInHierarchy,"Completion notebook present");var m=c.movement;m.Controller.enabled=false;m.transform.position+=Vector3.right*.8f;m.Controller.enabled=true;await Task.Delay(150);var facing=Quaternion.LookRotation(book.position-l.playerCamera.transform.position,Vector3.up)*Quaternion.Euler(l.view.spatial.notebookTilt);File.WriteAllText(D+"NotebookFacing.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{angle=Quaternion.Angle(book.rotation,facing),actual=book.rotation.eulerAngles.ToString(),expected=facing.eulerAngles.ToString(),parent=book.parent.name,position=book.position.ToString(),camera=l.playerCamera.transform.position.ToString(),flow=l.Flow.Step.ToString(),bookActive=book.gameObject.activeInHierarchy,viewEnabled=l.view.isActiveAndEnabled},Newtonsoft.Json.Formatting.Indented));Check(Quaternion.Angle(book.rotation,facing)<.1f,"Whole notebook faces the walking player");
 }catch(Exception e){error=e.ToString();}finally{if(p.IsPaused)p.Resume();c.enabled=true;l.Restart();l.presentation.space.overlay.Advance(2);}
 var report=Newtonsoft.Json.JsonConvert.SerializeObject(new{success=error==null,passed=checks.Count(x=>(bool)x.GetType().GetProperty("passed").GetValue(x)),checks,error},Newtonsoft.Json.Formatting.Indented);File.WriteAllText(D+"FinalBehaviourVerification.json",report);return report;}
}